1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "selfLink", expression = "java(\"/api/owners/\" + owner.getId())")
22	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
24	    @Mapping(target = "initials", expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
25	    @Mapping(target = "locality", expression = "java(org.springframework.samples.petclinic.util.CustomerCode.region(owner.getCustomerCode()))")
26	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
27	    @Mapping(target = "checkDigit", expression = "java(org.springframework.samples.petclinic.util.LuhnCheckDigit.of(owner.getCustomerCode()))")
28	    @Mapping(target = "fiscalYear", expression = "java(org.springframework.samples.petclinic.util.FiscalYear.label(owner.getRegistrationDate()))")
29	    @Mapping(target = "membershipNumber", expression = "java(owner.getCustomerCode() + \"-M\" + String.format(\"%02d\", org.springframework.samples.petclinic.util.FiscalYear.yearOf(owner.getRegistrationDate()) % 100))")
30	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
31	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
32	    @Mapping(target = "contactPreference", expression = "java((owner.getEmail() != null && !owner.getEmail().isBlank()) ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE)")
33	    @Mapping(target = "identityKey", expression = "java(org.springframework.samples.petclinic.util.OwnerIdentity.identityKey(owner))")
34	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
35	    @Mapping(target = "telephoneDisplay", expression = "java(org.springframework.samples.petclinic.util.TelephoneNormalizer.toDisplay(owner.getTelephone()))")
36	    OwnerDto toOwnerDto(Owner owner);
37	
38	    /**
39	     * Derives the owner's IANA {@code timezone} from its locality (region) via a fixed
40	     * region-to-timezone table: {@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne}
41	     * and {@code QLD -> Australia/Brisbane}. Returns {@code null} for a region not in the table.
42	     */
43	    default String timezone(Owner owner) {
44	        String region = org.springframework.samples.petclinic.util.CustomerCode.region(owner.getCustomerCode());
45	        if (region == null) {
46	            return null;
47	        }
48	        return switch (region) {
49	            case "NSW" -> "Australia/Sydney";
50	            case "VIC" -> "Australia/Melbourne";
51	            case "QLD" -> "Australia/Brisbane";
52	            default -> null;
53	        };
54	    }
55	
56	    /**
57	     * Derives the owner's {@code ageBand} from its {@code birthDate}, measured against its
58	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} from 18 to 64 and
59	     * {@code SENIOR} at 65 or older. Returns {@code null} when no birth date is present.
60	     */
61	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
62	        java.time.LocalDate birthDate = owner.getBirthDate();
63	        java.time.LocalDate asOf = owner.getRegistrationDate();
64	        if (birthDate == null || asOf == null) {
65	            return null;
66	        }
67	        int years = java.time.Period.between(birthDate, asOf).getYears();
68	        if (years < 18) {
69	            return OwnerDto.AgeBandEnum.MINOR;
70	        }
71	        if (years < 65) {
72	            return OwnerDto.AgeBandEnum.ADULT;
73	        }
74	        return OwnerDto.AgeBandEnum.SENIOR;
75	    }
76	
77	    /**
78	     * Computes the owner's {@code membershipPoints}. Starts at 0; adds 2 when a non-blank email is
79	     * present; adds 1 when {@code namesakeCount} is 0; adds 2 for a household of 3 or more; adds 3
80	     * when at least one fiscal year has elapsed since {@code registrationDate} (measured from
81	     * {@code registrationDate} to today, counting 1-July boundaries crossed).
82	     */
83	    default int membershipPoints(Owner owner) {
84	        int points = 0;
85	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
86	            points += 2;
87	        }
88	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
89	            points += 1;
90	        }
91	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
92	            points += 2;
93	        }
94	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
95	        if (registrationDate != null
96	                && org.springframework.samples.petclinic.util.FiscalYear.elapsed(
97	                        registrationDate, java.time.LocalDate.now()) >= 1) {
98	            points += 3;
99	        }
100	        return points;
101	    }
102	
103	    /**
104	     * Reports the owner's {@code membershipLevel}. Uses the level stored on the owner when present
105	     * (as stamped on creation), otherwise falls back to the level {@linkplain #derivedMembershipLevel
106	     * derived} from its {@code membershipPoints}.
107	     */
108	    default int membershipLevel(Owner owner) {
109	        Integer stored = owner.getMembershipLevel();
110	        return stored != null ? stored : derivedMembershipLevel(owner);
111	    }
112	
113	    /**
114	     * Derives the owner's {@code membershipLevel} from {@code membershipPoints}: 1 for 0-1 points,
115	     * 2 for 2-3 points, 3 for 4-5 points and 4 for 6 or more points.
116	     */
117	    default int derivedMembershipLevel(Owner owner) {
118	        int points = membershipPoints(owner);
119	        if (points <= 1) {
120	            return 1;
121	        }
122	        if (points <= 3) {
123	            return 2;
124	        }
125	        if (points <= 5) {
126	            return 3;
127	        }
128	        return 4;
129	    }
130	
131	    /**
132	     * Composes the owner's {@code salutation} from its honorific {@code title} and {@code lastName}:
133	     * {@code title + ' ' + lastName} when a non-blank title is present, or just the {@code lastName}
134	     * when no title is given.
135	     */
136	    default String salutation(Owner owner) {
137	        String title = owner.getTitle();
138	        if (title == null || title.isBlank()) {
139	            return owner.getLastName();
140	        }
141	        return title + " " + owner.getLastName();
142	    }
143	
